pub fn filler0(value: i64) -> i64 {
    return value + 0;
}

pub fn alpha(value: i64) -> i64 {
    let total = value + 10;
    let scaled = total * 2;
    return scaled - 3;
}

pub fn beta(value: i64) -> i64 {
    let total = value + 1;
    let scaled = total * 2;
    return scaled - 3;
}

pub fn gamma(value: i64) -> i64 {
    let total = value + 1;
    let scaled = total * 2;
    return scaled - 3;
}

pub fn filler1(value: i64) -> i64 {
    return value + 1;
}
